from app.domain.policies import tax_rate, vip_discount

def subtotal(items):
    return sum(item.qty * item.price for item in items)

def checkout_total(customer, items):
    base = subtotal(items)
    taxed = base * (1 + tax_rate(customer))
    return round(taxed - base * vip_discount(customer), 2)

